import { test } from "node:test";
import assert from "node:assert/strict";
import { z } from "zod";
import { kiemLenh, LenhMay } from "./sol.mjs";
test("hop le", () => {
  assert.deepEqual(kiemLenh({ may: "M01", lenh: "chay" }), { ok: true, lenh: { may: "M01", lenh: "chay" } });
  assert.deepEqual(kiemLenh({ may: "M12", lenh: "dat_toc_do", tocDo: 1500 }), { ok: true, lenh: { may: "M12", lenh: "dat_toc_do", tocDo: 1500 } });
  assert.equal(kiemLenh({ may: "M12", lenh: "dung", tocDo: 0 }).ok, true);
});
test("rang buoc cheo: dung chuoi prettifyError", () => {
  const r = kiemLenh({ may: "M01", lenh: "dat_toc_do" });
  assert.equal(r.ok, false);
  assert.equal((r as any).loi, "✖ can tocDo\n  → at tocDo");
});
test("khoa la + regex: dung z.prettifyError tren chinh loi do", () => {
  const x = { may: "X1", lenh: "chay", them: 1 };
  const r = kiemLenh(x) as any;
  assert.equal(r.ok, false);
  const kq = LenhMay.safeParse(x);
  assert.equal(kq.success, false);
  assert.equal(r.loi, z.prettifyError((kq as any).error));
  assert.ok(r.loi.includes("Unrecognized key"), "phai la doi tuong NGHIEM");
  assert.ok(r.loi.includes("✖ ma may sai\n  → at may"));
});
test("tocDo nguyen 0..3000", () => {
  assert.equal(kiemLenh({ may: "M01", lenh: "dat_toc_do", tocDo: 3001 }).ok, false);
  assert.equal(kiemLenh({ may: "M01", lenh: "dat_toc_do", tocDo: 1.5 }).ok, false);
  assert.equal(kiemLenh({ may: "M01", lenh: "dat_toc_do", tocDo: -1 }).ok, false);
  assert.equal(kiemLenh({ may: "M01", lenh: "quay" }).ok, false);
  assert.equal(kiemLenh(null).ok, false);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { z } from "zod";
import { NgayIso, SoThapPhan, BanGhi, giaiMa, maHoa } from "./sol.mjs";
test("NgayIso la codec hai chieu", () => {
  const d = z.decode(NgayIso, "2026-10-18T08:30:00+07:00");
  assert.ok(d instanceof Date);
  assert.equal(d.getTime(), Date.UTC(2026, 9, 18, 1, 30));
  assert.equal(z.encode(NgayIso, new Date(Date.UTC(2026, 0, 2, 3, 4, 5))), "2026-01-02T03:04:05.000Z");
  assert.throws(() => z.decode(NgayIso, "2026-10-18T08:30:00"), z.ZodError);
  assert.throws(() => z.decode(NgayIso, "2026-10-18 08:30"), z.ZodError);
});
test("SoThapPhan la codec hai chieu", () => {
  assert.equal(z.decode(SoThapPhan, "12.50"), 12.5);
  assert.equal(z.decode(SoThapPhan, "-3"), -3);
  assert.equal(z.encode(SoThapPhan, 12.5), "12.5");
  assert.throws(() => z.decode(SoThapPhan, "1e3"), z.ZodError);
  assert.throws(() => z.decode(SoThapPhan, "abc"), z.ZodError);
});
test("giaiMa / maHoa khu hoi", () => {
  const v = giaiMa({ ma: "T1", luc: "2026-10-18T00:00:00Z", giaTri: "7.25" });
  assert.equal(v.ma, "T1");
  assert.equal(v.luc.getTime(), Date.UTC(2026, 9, 18));
  assert.equal(v.giaTri, 7.25);
  assert.deepEqual(maHoa(v), { ma: "T1", luc: "2026-10-18T00:00:00.000Z", giaTri: "7.25" });
  assert.deepEqual(BanGhi.parse({ ma: "T2", luc: "2026-10-18T00:00:00Z", giaTri: "1" }).giaTri, 1);
});
test("du lieu sai nem ZodError ca hai chieu", () => {
  assert.throws(() => giaiMa({ ma: "T1", luc: "hom qua", giaTri: "1" }), z.ZodError);
  assert.throws(() => giaiMa({ ma: "T1", luc: "2026-10-18T00:00:00Z", giaTri: 1 }), z.ZodError);
  assert.throws(() => maHoa({ ma: "T1", luc: new Date(0), giaTri: Number.NaN } as any), z.ZodError);
  assert.throws(() => maHoa({ ma: "T1", luc: "2026-10-18" as any, giaTri: 1 } as any), z.ZodError);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import postgres from "postgres";
import { drizzle } from "drizzle-orm/postgres-js";
import { getTableName } from "drizzle-orm";
import { doKiem, demLoiTheoMay } from "./sol.mjs";
const sql = postgres(process.env.PG_URL!, { max: 4, onnotice: () => {} });
const db = drizzle(sql);
before(async () => {
  await sql`create table do_kiem(id serial primary key, may text not null, ket_qua text not null, luc timestamp with time zone not null, gia_tri double precision)`;
  const t0 = Date.UTC(2026, 9, 18, 0, 0, 0);
  const h = (m: number) => new Date(t0 + m * 60000);
  const dong: [string, string, Date, number | null][] = [
    ["M01", "NG", h(10), 1.5], ["M01", "NG", h(20), 2], ["M01", "OK", h(30), 3], ["M01", "NG", h(-30), 4],
    ["M02", "NG", h(5), null], ["M02", "NG", h(6), 5], ["M02", "NG", h(7), 6],
    ["M03", "NG", h(1), 7], ["M03", "NG", h(2), 8],
    ["M04", "OK", h(3), 9], ["M05", "NG", h(4), 10],
  ];
  const giaTri = dong.map(([m, k, l, g]) => `('${m}', '${k}', '${l.toISOString()}', ${g === null ? "null" : g})`).join(", ");
  await sql.unsafe(`insert into do_kiem(may, ket_qua, luc, gia_tri) values ${giaTri}`);
});
after(async () => { await sql.end({ timeout: 2 }); });
test("khai bao bang dung ten cot va kieu doc ra", async () => {
  assert.equal(getTableName(doKiem), "do_kiem");
  assert.equal((doKiem as any).ketQua.name, "ket_qua");
  assert.equal((doKiem as any).giaTri.name, "gia_tri");
  const [r] = await db.select().from(doKiem).limit(1) as any[];
  assert.ok(r.luc instanceof Date, "luc phai doc ra Date");
  assert.equal(typeof r.giaTri, "number");
  assert.equal(typeof r.ketQua, "string");
});
test("dem loi: loc may + moc thoi gian, sap soLoi giam roi may tang, soLoi la number", async () => {
  const kq = await demLoiTheoMay(db as any, ["M01", "M02", "M03", "M04"], new Date(Date.UTC(2026, 9, 18, 0, 0, 0)));
  assert.deepEqual(kq, [{ may: "M02", soLoi: 3 }, { may: "M01", soLoi: 2 }, { may: "M03", soLoi: 2 }]);
  assert.equal(typeof kq[0].soLoi, "number");
});
test("moc tu loai tru ban ghi truoc do; may khong co loi khong xuat hien", async () => {
  const kq = await demLoiTheoMay(db as any, ["M01", "M04", "M05"], new Date(Date.UTC(2026, 9, 18, 0, 6, 0)));
  assert.deepEqual(kq, [{ may: "M01", soLoi: 2 }]);
});
test("cacMay rong ⇒ [] va khong cham db", async () => {
  const bay = new Proxy({}, { get() { throw new Error("khong duoc cham db"); } });
  assert.deepEqual(await demLoiTheoMay(bay as any, [], new Date()), []);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import postgres from "postgres";
import { drizzle } from "drizzle-orm/postgres-js";
import { getTableName } from "drizzle-orm";
import { demLoi, congDon } from "./sol.mjs";
const sql = postgres(process.env.PG_URL!, { max: 10, onnotice: () => {} });
const db = drizzle(sql);
before(async () => {
  await sql`create table dem_loi(ma text primary key, so_lan integer not null default 0, cap_nhat timestamp with time zone not null default now())`;
});
after(async () => { await sql.end({ timeout: 2 }); });
test("khai bao bang", () => {
  assert.equal(getTableName(demLoi), "dem_loi");
  assert.equal((demLoi as any).soLan.name, "so_lan");
  assert.equal((demLoi as any).capNhat.name, "cap_nhat");
});
test("them moi roi cong don", async () => {
  assert.deepEqual(await congDon(db as any, "E01", 2), { ma: "E01", soLan: 2, moi: true });
  await sql`update dem_loi set cap_nhat = now() - interval '1 day' where ma = 'E01'`;
  assert.deepEqual(await congDon(db as any, "E01", 3), { ma: "E01", soLan: 5, moi: false });
  const [r] = await sql`select so_lan, cap_nhat > now() - interval '1 hour' as moi_cap_nhat from dem_loi where ma = 'E01'`;
  assert.equal(r.so_lan, 5);
  assert.equal(r.moi_cap_nhat, true, "cap_nhat phai duoc dat lai now()");
  assert.deepEqual(await congDon(db as any, "E02", 1), { ma: "E02", soLan: 1, moi: true });
});
test("dong thoi 20 loi goi tren cung ma: tong dung, dung MOT lan moi", async () => {
  const kq = await Promise.all(Array.from({ length: 20 }, () => congDon(db as any, "E09", 1)));
  const [r] = await sql`select so_lan from dem_loi where ma = 'E09'`;
  assert.equal(r.so_lan, 20);
  assert.equal(kq.filter((x) => x.moi).length, 1);
  assert.deepEqual(kq.map((x) => x.soLan).sort((a, b) => a - b), Array.from({ length: 20 }, (_, i) => i + 1));
});
test("them sai ⇒ RangeError, khong cham db", async () => {
  const bay = new Proxy({}, { get() { throw new Error("khong duoc cham db"); } });
  await assert.rejects(() => congDon(bay as any, "X", 0), RangeError);
  await assert.rejects(() => congDon(bay as any, "X", 1.5), RangeError);
  await assert.rejects(() => congDon(bay as any, "X", -2), RangeError);
});

import "./dom.mjs";
import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { render, screen, fireEvent, act, cleanup } from "@testing-library/react";
import { FormDatTen } from "./sol.mjs";
afterEach(cleanup);
function hoan() { let ok: any, loi: any; const p = new Promise<string>((a, b) => { ok = a; loi = b; }); return { p, ok, loi }; }
const nut = () => screen.getByRole("button", { name: "Lưu" }) as HTMLButtonElement;
test("thanh cong: trim, cho (disabled), hien status, lam trong o nhap", async () => {
  const h = hoan(); const goi: string[] = [];
  render(<FormDatTen luu={(t: string) => { goi.push(t); return h.p; }} />);
  const o = screen.getByLabelText("Tên") as HTMLInputElement;
  fireEvent.change(o, { target: { value: "  Máy 01  " } });
  await act(async () => { fireEvent.click(nut()); });
  // ⚠ React 19 VƯỚNG mọi transition vào action async còn treo ⇒ luôn giải hứa trong finally, kẻo các test sau kẹt theo.
  let dangCho: boolean;
  try {
    assert.deepEqual(goi, ["Máy 01"]);
    dangCho = nut().disabled;
  } finally {
    await act(async () => { h.ok("Đã lưu Máy 01"); });
  }
  assert.equal(dangCho, true, "nut phai disabled khi dang cho");
  assert.equal(screen.getByRole("status").textContent, "Đã lưu Máy 01");
  assert.equal(nut().disabled, false);
  assert.equal((screen.getByLabelText("Tên") as HTMLInputElement).value, "");
  assert.equal(screen.queryByRole("alert"), null);
});
test("rong sau trim: Thieu ten, khong goi luu", async () => {
  const goi: string[] = [];
  render(<FormDatTen luu={async (t: string) => { goi.push(t); return "x"; }} />);
  fireEvent.change(screen.getByLabelText("Tên"), { target: { value: "   " } });
  await act(async () => { fireEvent.click(nut()); });
  assert.equal(goi.length, 0);
  assert.equal(screen.getByRole("alert").textContent, "Thiếu tên");
});
test("luu nem loi: alert = message, roi gui lai thanh cong thi alert bien mat", async () => {
  let lan = 0;
  render(<FormDatTen luu={async (t: string) => { lan++; if (lan === 1) throw new Error("Trùng tên " + t); return "OK " + t; }} />);
  fireEvent.change(screen.getByLabelText("Tên"), { target: { value: "A" } });
  await act(async () => { fireEvent.click(nut()); });
  assert.equal(screen.getByRole("alert").textContent, "Trùng tên A");
  fireEvent.change(screen.getByLabelText("Tên"), { target: { value: "B" } });
  await act(async () => { fireEvent.click(nut()); });
  assert.equal(screen.getByRole("status").textContent, "OK B");
  assert.equal(screen.queryByRole("alert"), null);
});

import "./dom.mjs";
import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { Suspense } from "react";
import { render, screen, act, cleanup } from "@testing-library/react";
import { ThongTinMay, KhungMay } from "./sol.mjs";
afterEach(cleanup);
type TT = { ten: string; trangThai: string };
function hoan() { let ok: any; const p = new Promise<TT>((a) => { ok = a; }); return { p, ok }; }
test("ThongTinMay SUSPEND trong Suspense cua nguoi goi", async () => {
  const h = hoan();
  await act(async () => { render(<Suspense fallback={<i>CHO</i>}><ThongTinMay duLieu={h.p} /></Suspense>); });
  const coFallback = !!screen.queryByText("CHO");
  await act(async () => { h.ok({ ten: "M01", trangThai: "CHAY" }); });
  assert.ok(coFallback, "phai hien fallback cua Suspense ben ngoai khi promise chua xong");
  assert.equal(screen.queryByText("CHO"), null);
  assert.ok(screen.getByText("M01 — CHAY"));
});
test("KhungMay: fallback Dang tai… roi noi dung; promise moi ⇒ lai Dang tai…", async () => {
  const a = hoan();
  let r: any;
  await act(async () => { r = render(<KhungMay duLieu={a.p} />); });
  assert.ok(screen.getByText("Đang tải…"));
  await act(async () => { a.ok({ ten: "M02", trangThai: "DUNG" }); });
  assert.ok(screen.getByText("M02 — DUNG"));
  const b = hoan();
  await act(async () => { r.rerender(<KhungMay duLieu={b.p} />); });
  const coFallback = !!screen.queryByText("Đang tải…");
  await act(async () => { b.ok({ ten: "M03", trangThai: "LOI" }); });
  assert.ok(coFallback, "promise moi chua xong ⇒ fallback");
  assert.ok(screen.getByText("M03 — LOI"));
  assert.equal(screen.queryByText("M02 — DUNG"), null);
});
test("promise da xong san ⇒ hien noi dung", async () => {
  const p = Promise.resolve({ ten: "M09", trangThai: "CHAY" });
  await act(async () => { render(<KhungMay duLieu={p} />); });
  assert.ok(screen.getByText("M09 — CHAY"));
});

import "./dom.mjs";
import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { render, screen, fireEvent, act, cleanup } from "@testing-library/react";
import { BangTab } from "./sol.mjs";
afterEach(cleanup);
const bam = async (ten: string) => { await act(async () => { fireEvent.click(screen.getByRole("button", { name: ten })); }); };
test("giu state + DOM khi an, don effect khi an, chay lai khi hien", async () => {
  const log: string[] = [];
  await act(async () => { render(<BangTab ghiNhan={(s: string) => log.push(s)} />); });
  assert.deepEqual(log, ["mo"]);
  await bam("Tăng"); await bam("Tăng");
  assert.ok(screen.getByText("Đếm: 2"));
  await bam("Cài đặt");
  assert.deepEqual(log, ["mo", "dong"], "an tab Do phai don effect");
  fireEvent.change(screen.getByLabelText("Ghi chú"), { target: { value: "dầu máy" } });
  await bam("Đo");
  assert.deepEqual(log, ["mo", "dong", "mo"], "hien lai phai chay lai effect");
  assert.ok(screen.getByText("Đếm: 2"), "state dem phai con");
  await bam("Tăng");
  assert.ok(screen.getByText("Đếm: 3"));
  await bam("Cài đặt");
  assert.equal((screen.getByLabelText("Ghi chú") as HTMLInputElement).value, "dầu máy", "o ghi chu phai giu chu da go");
  assert.deepEqual(log, ["mo", "dong", "mo", "dong"]);
});
test("tab an van con trong DOM (khong unmount) nhung bi an", async () => {
  await act(async () => { render(<BangTab ghiNhan={() => {}} />); });
  await bam("Tăng");
  await bam("Cài đặt");
  const span = screen.getByText("Đếm: 1");
  let e: HTMLElement | null = span;
  let an = false;
  while (e) { if (e.style && e.style.display === "none") an = true; e = e.parentElement; }
  assert.ok(an, "noi dung tab an phai bi display:none");
});

import "./dom.mjs";
import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { render, act, cleanup, screen } from "@testing-library/react";
import { PhongTheoDoi } from "./sol.mjs";
afterEach(cleanup);
test("chi ket noi lai khi doi phong; dung props moi nhat khi nhan gia tri", async () => {
  const mo: string[] = [], dong: string[] = [];
  let phat: ((v: number) => void) | null = null;
  const ketNoi = (phong: string, cb: (v: number) => void) => { mo.push(phong); phat = cb; return () => { dong.push(phong); }; };
  const bd1: string[] = [], bd2: string[] = [];
  let r: any;
  await act(async () => { r = render(<PhongTheoDoi phong="A" donVi="C" nguong={50} baoDong={(s: string) => bd1.push(s)} ketNoi={ketNoi} />); });
  assert.ok(screen.getByText("Phòng A"));
  assert.deepEqual(mo, ["A"]);
  await act(async () => { phat!(40); phat!(60); });
  assert.deepEqual(bd1, ["A: 60.0°C"]);
  await act(async () => { r.rerender(<PhongTheoDoi phong="A" donVi="F" nguong={70} baoDong={(s: string) => bd2.push(s)} ketNoi={(p: string, cb: any) => ketNoi(p, cb)} />); });
  assert.deepEqual(mo, ["A"], "doi donVi/nguong/baoDong/ketNoi KHONG duoc ket noi lai");
  assert.deepEqual(dong, []);
  await act(async () => { phat!(60); phat!(80); });
  assert.deepEqual(bd1, ["A: 60.0°C"], "khong duoc goi baoDong cu");
  assert.deepEqual(bd2, ["A: 176.0°F"]);
  await act(async () => { r.rerender(<PhongTheoDoi phong="B" donVi="F" nguong={70} baoDong={(s: string) => bd2.push(s)} ketNoi={ketNoi} />); });
  assert.deepEqual(mo, ["A", "B"]);
  assert.deepEqual(dong, ["A"]);
  await act(async () => { phat!(100); });
  assert.deepEqual(bd2, ["A: 176.0°F", "B: 212.0°F"]);
  r.unmount();
  assert.deepEqual(dong, ["A", "B"]);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { DataType, StatusCodes } from "node-opcua";
import { batOpcua } from "./opcua.mjs";
import { docNhieuBien } from "./sol.mjs";
let m: any;
const cho = (ms: number) => new Promise((r) => setTimeout(r, ms));
async function choVe0(f: () => number) { for (let i = 0; i < 40 && f() !== 0; i++) await cho(50); return f(); }
before(async () => {
  m = await batOpcua(({ ns, objects }: any) => {
    const f = ns.addFolder(objects, { browseName: "Line1" });
    const a = ns.addVariable({ componentOf: f, browseName: "Temp", nodeId: "s=Line1.Temp", dataType: "Double" });
    a.setValueFromSource({ dataType: DataType.Double, value: 21.5 });
    const b = ns.addVariable({ componentOf: f, browseName: "Count", nodeId: "s=Line1.Count", dataType: "Int32" });
    b.setValueFromSource({ dataType: DataType.Int32, value: 42 });
    const c = ns.addVariable({ componentOf: f, browseName: "Hong", nodeId: "s=Line1.Hong", dataType: "Double" });
    c.setValueFromSource({ dataType: DataType.Double, value: 7 }, StatusCodes.BadSensorFailure);
  });
});
after(async () => { await m?.tat(); });
test("doc gop MOT ReadRequest; Good ⇒ so, khac Good ⇒ null; dong phien", async () => {
  const ns = m.ns.index;
  const ids = [`ns=${ns};s=Line1.Temp`, `ns=${ns};s=Line1.Count`, `ns=${ns};s=Line1.Hong`, `ns=${ns};s=Line1.KhongCo`];
  const truoc = m.yeuCau.ReadRequest ?? 0;
  const kq = await docNhieuBien(m.endpoint, ids);
  assert.deepEqual(kq, { [ids[0]]: 21.5, [ids[1]]: 42, [ids[2]]: null, [ids[3]]: null });
  assert.equal((m.yeuCau.ReadRequest ?? 0) - truoc, 1, "phai doc tat ca trong MOT lan session.read");
  assert.equal(await choVe0(m.soPhien), 0, "phien phai duoc dong");
  assert.equal(await choVe0(m.soKenh), 0, "phai ngat ket noi");
});
test("goi lan hai van dung (khong ro tai nguyen)", async () => {
  const ns = m.ns.index;
  const id = `ns=${ns};s=Line1.Count`;
  assert.deepEqual(await docNhieuBien(m.endpoint, [id]), { [id]: 42 });
  assert.equal(await choVe0(m.soPhien), 0);
});
test("may chu khong ton tai ⇒ nem loi nhanh", { timeout: 20000 }, async () => {
  const t0 = Date.now();
  await assert.rejects(() => docNhieuBien("opc.tcp://127.0.0.1:1", ["ns=1;s=X"]));
  assert.ok(Date.now() - t0 < 15000, "khong duoc thu lai vo han");
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { DataType } from "node-opcua";
import { batOpcua } from "./opcua.mjs";
import { thuMauThayDoi } from "./sol.mjs";
let m: any;
let hen: any;
const cho = (ms: number) => new Promise((r) => setTimeout(r, ms));
async function choVe0(f: () => number) { for (let i = 0; i < 40 && f() !== 0; i++) await cho(50); return f(); }
before(async () => {
  m = await batOpcua(({ ns, objects }: any) => {
    const v = ns.addVariable({ organizedBy: objects, browseName: "Dem", nodeId: "s=Line1.Dem", dataType: "Int32", minimumSamplingInterval: 20 });
    let n = 100;
    v.setValueFromSource({ dataType: DataType.Int32, value: n });
    hen = setInterval(() => { n += 1; v.setValueFromSource({ dataType: DataType.Int32, value: n }); }, 40);
  });
});
after(async () => { clearInterval(hen); await m?.tat(); });
test("thu dung soMau gia tri tang dan bang subscription, khong tham do", async () => {
  const nodeId = `ns=${m.ns.index};s=Line1.Dem`;
  const doc0 = m.yeuCau.ReadRequest ?? 0;
  const kq = await thuMauThayDoi(m.endpoint, nodeId, 6, 50);
