const goi = async (ma, them) => { const r = await sql`select * from ghi_dem(${ma}, ${them}::integer)`; assert.equal(r.length, 1, "phai tra dung MOT hang"); return { ma: r[0].ma, so_lan: r[0].so_lan, moi: r[0].moi }; };
